function debounce(fn, ms) {
  let timer;
  return (x) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(x), ms);
  };
}

function throttle(fn, ms) {
  let waiting = false;
  return (x) => {
    if (waiting) return;
    waiting = true;
    fn(x);
    setTimeout(() => (waiting = false), ms);
  };
}

const d = debounce((x) => console.log("d" + x), 40);
const t = throttle((x) => console.log("t" + x), 40);

for (const at of [0, 20, 80]) {
  setTimeout(() => (d(at), t(at)), at);
}
